with o as (
  insert into orders (email, productId, amountCents, status, stripeSessionId, paidAt, expiresAt, downloadCount, createdAt)
       select 'maya.chen@example.com', id, 2400, 'paid', 'cs_test_seed_01', now() - interval '27 days 11 hours', now() - interval '27 days 11 hours' + interval '30 days', 2, now() - interval '27 days 11 hours'
         from products where slug = 'folio-portfolio-template'
  returning id, paidAt
)
insert into downloads (orderId, createdAt)
     select o.id, o.paidAt + (g * interval '37 minutes') from o, generate_series(1, 2) g;

